{{-- Replace this tiny node on Livewire updates so Alpine formats it again after every poll. UTC stays the fallback and hover text. --}}
<time wire:replace.self datetime="{{ $instant->toIso8601String() }}" title="{{ $instant->utc()->format('M j, Y, g:i A \\U\\T\\C') }}" x-data x-init="const date = new Date($el.dateTime); if (!isNaN(date)) $el.textContent = new Intl.DateTimeFormat('en-US', {year: 'numeric', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', timeZoneName: 'short'}).format(date)">{{ $instant->utc()->format('M j, Y, g:i A \\U\\T\\C') }}</time>
